import { Component, ElementRef, ViewChild } from '@angular/core';
import { timeout } from 'rxjs';

@Component({
    selector: 'app-transaction-start',
    host: { class: 'childRouteFlex' },
    templateUrl: './transaction-start.component.html',
    styleUrls: ['./transaction-start.component.css']
})
export class TransactionStartComponent {
    showButtonChoseIsIncome = false;
    firstLoad = true;

    buttonCreate: any;
    buttonCreateBefore: any;

    constructor(private elRef: ElementRef) {}

    ngOnInit() {
        this.buttonCreate =
            this.elRef.nativeElement.querySelector('#buttonCreate');
        this.buttonCreateBefore = window.getComputedStyle(
            this.buttonCreate,
            ':before'
        );
        this.buttonCreate.addEventListener('mousemove', (e: any) => {
            const rect = this.buttonCreate.getBoundingClientRect(),
                mouseX = e.clientX - rect.left,
                mouseY = e.clientY - rect.top;

            // set width and height of the before element
            // based on the mouse position, the more the posizion is close to the center the more the element is small
            const width = Math.abs(rect.width / 2 - mouseX) / 2;
            // height change only of an amount of 20 %, the rest is based on the width
            const height = Math.abs(rect.height / 2 - mouseY) + width * 0.2;

            this.buttonCreate.style.setProperty('--width', width + 'px');
            this.buttonCreate.style.setProperty('--height', height + 'px');

            let x = mouseX - width / 2;
            let y = mouseY - height / 2;

            this.buttonCreate.style.setProperty('--mouse-x', x + 'px');
            this.buttonCreate.style.setProperty('--mouse-y', y + 'px');

            console.log(rect.width, mouseX - rect.left);
            let progress = (mouseX * 100) / rect.width;
            // console.log(this.blendColors('#00bfa5', '#ff1744', progress));
            console.log(this.colorMixer([0, 191, 165], [255, 23, 68], progress));
            // this.buttonCreate.style.setProperty('--background-color', );
        });
    }

    CreateTransaction() {
        this.showButtonChoseIsIncome = !this.showButtonChoseIsIncome;
        this.firstLoad = false;
    }


function toRGBA(d) {
	const l = d.length;
	const rgba = {};
	if (d.slice(0, 3).toLowerCase() === 'rgb') {
		d = d.replace(' ', '').split(',');
		rgba[0] = parseInt(d[0].slice(d[3].toLowerCase() === 'a' ? 5 : 4), 10);
		rgba[1] = parseInt(d[1], 10);
		rgba[2] = parseInt(d[2], 10);
		rgba[3] = d[3] ? parseFloat(d[3]) : -1;
	} else {
		if (l < 6) d = parseInt(String(d[1]) + d[1] + d[2] + d[2] + d[3] + d[3] + (l > 4 ? String(d[4]) + d[4] : ''), 16);
		else d = parseInt(d.slice(1), 16);
		rgba[0] = (d >> 16) & 255;
		rgba[1] = (d >> 8) & 255;
		rgba[2] = d & 255;
		rgba[3] = l === 9 || l === 5 ? r((((d >> 24) & 255) / 255) * 10000) / 10000 : -1;
	}
	return rgba;
}

// @ts-ignore
function blend(from, to, p = 0.5) {
	from = from.trim();
	to = to.trim();
	const b = p < 0;
	p = b ? p * -1 : p;
	const f = toRGBA(from);
	const t = toRGBA(to);
	if (to[0] === 'r') {
		return 'rgb' + (to[3] === 'a' ? 'a(' : '(') +
			r(((t[0] - f[0]) * p) + f[0]) + ',' +
			r(((t[1] - f[1]) * p) + f[1]) + ',' +
			r(((t[2] - f[2]) * p) + f[2]) + (
				f[3] < 0 && t[3] < 0 ? '' : ',' + (
					f[3] > -1 && t[3] > -1
						? r((((t[3] - f[3]) * p) + f[3]) * 10000) / 10000
						: t[3] < 0 ? f[3] : t[3]
				)
			) + ')';
	}
	// @ts-ignore
	return '#' + (0x100000000 + ((
		f[3] > -1 && t[3] > -1
			? r((((t[3] - f[3]) * p) + f[3]) * 255)
			: t[3] > -1 ? r(t[3] * 255) : f[3] > -1 ? r(f[3] * 255) : 255
		) * 0x1000000) +
		(r(((t[0] - f[0]) * p) + f[0]) * 0x10000) +
		(r(((t[1] - f[1]) * p) + f[1]) * 0x100) +
		r(((t[2] - f[2]) * p) + f[2])
	).toString(16).slice(f[3] > -1 || t[3] > -1 ? 1 : 3);
}

}
<div class="mainChild">
    <div class="list-container">
        <app-transaction-list></app-transaction-list>
    </div>
</div>

<div
	id="buttonCreate"
    class="default-button bottom-button invert-button"
    ngClass="{{ showButtonChoseIsIncome ? 'active' : '' }}"
>
    <div
        class="button-create"
        ngClass="{{ showButtonChoseIsIncome ? 'active' : !firstLoad ? 'off' : '' }}"
        (click)="CreateTransaction()"
    >
        <div class="button-create-text secondary">
            <span *ngIf="!showButtonChoseIsIncome">Create Transaction</span>
            <span *ngIf="showButtonChoseIsIncome">X</span>
        </div>
    </div>
    <div class="income-expense-container">
        <div class="sub-button">
			<span class="income-amount">Income</span>
		</div>
        <div class="sub-button">
			<span class="expense-amount">Expense</span>
		</div>
    </div>
</div>
